import{_ as n,C as e,o as s,c as l,E as a,a7 as c}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"Scrollix Privacy Policy","description":"Privacy Policy for Scrollix, presented within Policy Hub.","frontmatter":{"title":"Scrollix Privacy Policy","description":"Privacy Policy for Scrollix, presented within Policy Hub."},"headers":[],"relativePath":"apps/scrollix/privacy.md","filePath":"apps/scrollix/privacy.md"}'),d={name:"apps/scrollix/privacy.md"};function p(h,o,u,f,m,v){const r=e("AppBreadcrumbs"),i=e("AppSubnav"),t=e("CopyStandaloneUrl");return s(),l("div",null,[a(r,{"app-id":"scrollix",current:"Privacy Policy"}),a(i,{"app-id":"scrollix"}),a(t,{path:"/privacy/scrollix",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Scrollix privacy policy"}),o[0]||(o[0]=c('<h1 id="privacy-policy-for-scrollix" tabindex="-1">Privacy Policy for Scrollix <a class="header-anchor" href="#privacy-policy-for-scrollix" aria-label="Permalink to &quot;Privacy Policy for Scrollix&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Scrollix is a curated media-feed application developed by <strong>Anand Raja</strong>. It displays videos, social posts, and web articles listed in a configured Google Sheet and lets you open, play, save, or share supported content.</p><p>Scrollix has no advertising, developer-operated analytics, or general-purpose online user account.</p><h2 id="curated-feed-data" tabindex="-1">Curated Feed Data <a class="header-anchor" href="#curated-feed-data" aria-label="Permalink to &quot;Curated Feed Data&quot;">​</a></h2><p>Scrollix reads a configured Google Sheet through Google&#39;s Visualization endpoint. Rows can contain a serial number, media type, URL or video identifier, protected-status flag, title, description, optional YouTube start time, and share-link hash.</p><p>The complete fetched feed is cached unencrypted in localStorage for offline fallback, including rows marked Protected. A Protected row is hidden in the interface until local login; the flag does not encrypt the row or change Google Sheet permissions.</p><p>Google receives the spreadsheet and tab identifiers plus standard connection information such as IP address, user agent, request time, and requested resource. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><h2 id="media-platforms-and-external-sites" tabindex="-1">Media Platforms and External Sites <a class="header-anchor" href="#media-platforms-and-external-sites" aria-label="Permalink to &quot;Media Platforms and External Sites&quot;">​</a></h2><p>Depending on the selected item, Scrollix embeds, resolves, previews, or opens content from services such as YouTube, Instagram, Facebook, TikTok, Dailymotion, Vimeo, Reddit, and independent websites. Those services can receive your IP address, user agent, referrer or app origin, request time, content identifier, cookies or account state, and playback or interaction information under their own policies.</p><p>Loading YouTube content uses the YouTube iframe API. Facebook, Instagram, TikTok, Dailymotion, Vimeo, and other embeds use their respective players or pages. Opening a post can use an in-app reader, the Android app associated with the link, or your browser.</p><h2 id="link-resolution-and-previews" tabindex="-1">Link Resolution and Previews <a class="header-anchor" href="#link-resolution-and-previews" aria-label="Permalink to &quot;Link Resolution and Previews&quot;">​</a></h2><p>Scrollix can resolve Facebook and TikTok share URLs and fetch Open Graph metadata such as title, description, preview image, destination URL, and site logo. On Android, this is fetched directly from the destination on the device. On the web, Microlink may receive the target URL as a preview or redirect-resolution request.</p><p>Preview metadata can be cached unencrypted for up to seven days, with a maximum of 300 entries. Destination sites and Microlink receive standard request information and apply their own privacy policies.</p><h2 id="offline-android-posts" tabindex="-1">Offline Android Posts <a class="header-anchor" href="#offline-android-posts" aria-label="Permalink to &quot;Offline Android Posts&quot;">​</a></h2><p>On Android, you can save up to five supported posts for offline reading. Scrollix downloads and stores the post URL, title, description, full fetched HTML, and save time in unencrypted localStorage. Saved pages may contain third-party content or embedded references. You can remove each saved post from the app.</p><h2 id="login-and-app-lock" tabindex="-1">Login and App Lock <a class="header-anchor" href="#login-and-app-lock" aria-label="Permalink to &quot;Login and App Lock&quot;">​</a></h2><p>Optional local login stores the entered username and successful SHA-1 password hash in localStorage. It is an interface access gate, not an online identity service.</p><p>An optional PIN uses a salted PBKDF2-SHA-256 verifier. On supported Android devices, optional biometric unlock uses Android BiometricPrompt and Android Keystore. Scrollix does not receive or store biometric templates. These controls restrict the interface but do not encrypt cached feed rows, previews, or offline posts.</p><h2 id="sharing-and-preferences" tabindex="-1">Sharing and Preferences <a class="header-anchor" href="#sharing-and-preferences" aria-label="Permalink to &quot;Sharing and Preferences&quot;">​</a></h2><p>Scrollix can copy web or <code>scrollix://</code> Android video links to the system clipboard. Clipboard contents may be visible to Android, keyboard software, clipboard history, and permitted apps. The app stores preferences such as whether posts open in the in-app reader and a temporary browser install-prompt dismissal.</p><h2 id="information-received-by-the-developer" tabindex="-1">Information Received by the Developer <a class="header-anchor" href="#information-received-by-the-developer" aria-label="Permalink to &quot;Information Received by the Developer&quot;">​</a></h2><p>The developer does not automatically receive your username, login hash, PIN data, biometric data, cached content, offline posts, playback history, or copied links. Google, media platforms, preview services, and destination sites receive the requests described above. If you contact support, the developer receives the information you choose to send.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Scrollix uses internet access for feed retrieval, previews, media playback, and websites; biometric permission when enabled; and clipboard access after copy actions. The reviewed app does not request location, contacts, phone, SMS, call-log, camera, microphone, storage, or notification permission.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>You can remove saved offline posts individually and log out to remove local login records. To remove all caches, preferences, and security settings, clear Scrollix app storage or uninstall it; in a browser, clear site storage and cache. This does not delete source Google Sheet rows, third-party platform records, clipboard history, or content saved elsewhere.</p><h2 id="content-and-safety" tabindex="-1">Content and Safety <a class="header-anchor" href="#content-and-safety" aria-label="Permalink to &quot;Content and Safety&quot;">​</a></h2><p>Scrollix does not own or control third-party content. Availability, accuracy, suitability, licensing, and safety remain the responsibility of the relevant publisher and platform.</p><h2 id="changes-and-contact" tabindex="-1">Changes and Contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and Contact&quot;">​</a></h2><p>This policy may be updated when Scrollix features or data practices change.</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',33))])}const g=n(d,[["render",p]]);export{b as __pageData,g as default};
